require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';Auth::requireRole('admin');$required=['users','donor_profiles','donor_notification_preferences','hospitals','mfa_otps','emergency_requests','emergency_invites','emergency_escalations','hospital_referrals','organ_interests','organ_coordination_requests','blood_inventory','blood_transfer_requests','donation_campaigns','campaign_registrations','security_events','system_settings','audit_logs'];$checks=[];try{$tables=db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);foreach($required as $t)$checks[]=['label'=>'Database table: '.$t,'ok'=>in_array($t,$tables,true),'detail'=>in_array($t,$tables,true)?'Available':'Missing'];$checks[]=['label'=>'Database connection','ok'=>true,'detail'=>'Connected to '.config('db','name')];}catch(Throwable $e){$checks[]=['label'=>'Database connection','ok'=>false,'detail'=>$e->getMessage()];}$checks[]=['label'=>'Application key','ok'=>strlen((string)config('app','key'))>=32,'detail'=>strlen((string)config('app','key'))>=32?'Configured':'Set a long APP_KEY'];$checks[]=['label'=>'Session timeout','ok'=>(int)config('app','session_timeout_minutes')>=5,'detail'=>(string)config('app','session_timeout_minutes').' minutes'];$checks[]=['label'=>'Email delivery','ok'=>(string)config('app','env')==='local'||((string)config('brevo','api_key')!==''&&(string)config('brevo','sender_email')!==''),'detail'=>(string)config('app','env')==='local'?'Local simulation allowed':'Production provider check'];$checks[]=['label'=>'SMS delivery','ok'=>(string)config('app','env')==='local'||(string)config('textlk','api_token')!=='','detail'=>(string)config('app','env')==='local'?'Local simulation/OTP mode allowed':'Production provider check'];$pageTitle='System Health';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Administration</div><h1>System health</h1><p class="page-note">Basic configuration and database checks for the local prototype.</p></div></div><?=admin_nav()?><div class="table-wrap"><table class="table"><thead><tr><th>Check</th><th>Status</th><th>Detail</th></tr></thead><tbody><?php foreach($checks as $c):?><tr><td><?=e($c['label'])?></td><td><span class="badge <?=$c['ok']?'green':'red'?>"><?=$c['ok']?'PASS':'CHECK'?></span></td><td><?=e($c['detail'])?></td></tr><?php endforeach;?></tbody></table></div></div></section>
